<?php namespace App\Controllers; use App\Models\ProductModel;
class Products extends BaseController { private ProductModel $m; public function __construct(){ $this->m=new ProductModel(); } public function index(){ return view('products/index',['title'=>'Products','rows'=>$this->m->orderBy('id','DESC')->findAll()]); } private function save($id=null){ $data=['name'=>trim($this->request->getPost('name')),'price'=>(float)$this->request->getPost('price'),'stock_quantity'=>(int)$this->request->getPost('stock_quantity'),'created_at'=>date('Y-m-d H:i:s')]; $file=$this->request->getFile('image'); if($file && $file->isValid() && in_array($file->getMimeType(),['image/jpeg','image/png','image/webp'],true)){ $name=$file->getRandomName(); $file->move(FCPATH.'uploads/products',$name); $data['image']=$name; } if(!$this->validate(['name'=>'required|max_length[100]','price'=>'required|decimal','stock_quantity'=>'required|is_natural'])) return redirect()->back()->withInput()->with('errors',$this->validator->getErrors()); $id ? $this->m->update($id,$data) : $this->m->insert($data); return redirect()->to('/products')->with('success','Product saved.'); } public function create(){ return $this->request->getMethod()==='POST' ? $this->save() : view('products/form',['title'=>'Add Product','row'=>null]); } public function edit($id){ return $this->request->getMethod()==='POST' ? $this->save($id) : view('products/form',['title'=>'Edit Product','row'=>$this->m->find($id)]); } public function delete($id){ $this->m->delete($id); return redirect()->to('/products')->with('success','Product deleted.'); } }
